 import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  const [message, setMessage] = useState("");
  const [status, setStatus] = useState(true);

  useEffect(() => {
    fetch("http://backend:5000/api/message")
      .then(res => res.json())
      .then(data => {
        setMessage(data.message);
        setStatus(true);
      })
      .catch(() => {
        setMessage("Backend not reachable ❌");
        setStatus(false);
      });
  }, []);

  return (
    <div className="container">
      <head></head>
      <h1 className="title">🚀 DevOps Demo Dashboard</h1>

      <div className="section">
        <h2>🔗 Backend Status</h2>
        <div className="card">
          <p className={status ? "status-success" : "status-error"}>
            {message}
          </p>
        </div>
      </div>

      <div className="section">
        <h2>📌 Project Info</h2>
        <div className="card">
          <ul className="list">
            <li><b>Frontend:</b> React.js</li>
            <li><b>Backend:</b> Node.js (Express)</li>
            <li><b>API:</b> /api/message</li>
            <li><b>Ports:</b> 3000 (Frontend), 5000 (Backend)</li>
          </ul>
        </div>
      </div>

      <div className="section">
        <h2>⚙️ DevOps Workflow</h2>
        <div className="card">
          <ol className="list">
            <li>Code in VS Code</li>
            <li>Version control using Git</li>
            <li>Containerization using Docker</li>
            <li>CI/CD using Jenkins</li>
            <li>Deployment on AWS</li>
          </ol>
        </div>
      </div>

      <div className="footer">
        <p>Built for DevOps Learning 🚀</p>
      </div>

    </div>
  );
}

export default App;
